using Aspire.Hosting.Testing;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.AI.Evaluation;
using Microsoft.Extensions.AI.Evaluation.Quality;
using Microsoft.Extensions.AI.Evaluation.Reporting;
using Microsoft.Extensions.DependencyInjection;

namespace MyApp.Evals;

[TestClass]
public class EvalTests
{
    private static DistributedApplicationTestingBuilder _appHost = null!;
    private static DistributedApplication _app = null!;
    private static IChatClient _chatClient = null!;
    private static ReportingConfiguration _reportingConfig = null!;

    [ClassInitialize]
    public static async Task Setup(TestContext context)
    {
        _appHost = await DistributedApplicationTestingBuilder.CreateAsync<Projects.MyApp_AppHost>();
        _app = await _appHost.BuildAsync();
        await _app.StartAsync();

        _chatClient = _app.Services.GetRequiredService<IChatClient>();

        _reportingConfig = CreateReportingConfiguration();
    }

    [ClassCleanup]
    public static async Task Cleanup()
    {
        await _app.DisposeAsync();
        await _appHost.DisposeAsync();
    }

    private static ReportingConfiguration CreateReportingConfiguration()
    {
        var path = Path.Combine(Directory.GetCurrentDirectory(), "eval-reports");
        var storageFactory = DiskBasedReportingConfiguration.CreateReportStorageFactory(path);

        return DiskBasedReportingConfiguration.Create(
            storageFactory: storageFactory,
            evaluators:
            [
                new CoherenceEvaluator(),
                new RelevanceEvaluator(),
                new FluencyEvaluator(),
            ],
            chatConfiguration: new ChatConfiguration(_chatClient));
    }

    [TestMethod]
    public async Task Chat_ReturnsCoherentResponse()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_ReturnsCoherentResponse));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "What is the capital of France? Answer in one sentence.")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllMetricsPassed();
    }

    [TestMethod]
    public async Task Chat_FollowsInstructions()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_FollowsInstructions));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.System, "You are a helpful assistant. Always respond in exactly three bullet points."),
            new(ChatRole.User, "What are the benefits of exercise?")
        };

        var response = await _chatClient.GetResponseAsync(messages);
        messages.Add(response.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllMetricsPassed();
    }

    [TestMethod]
    public async Task Chat_HandlesMultiTurnConversation()
    {
        await using var scenario = await _reportingConfig.CreateScenarioRunAsync(
            scenarioName: nameof(Chat_HandlesMultiTurnConversation));

        var messages = new List<ChatMessage>
        {
            new(ChatRole.User, "My name is Alice."),
        };

        var response1 = await _chatClient.GetResponseAsync(messages);
        messages.Add(response1.Message);

        messages.Add(new ChatMessage(ChatRole.User, "What is my name?"));

        var response2 = await _chatClient.GetResponseAsync(messages);
        messages.Add(response2.Message);

        await scenario.EvaluateAsync(messages);

        scenario.AssertAllMetricsPassed();
    }
}

